'use strict';
// server/test/platform-migrations.test.js — the platform's migrations folder (server/netlify/database/migrations, generated by
// server/db/platform-migrations.js from server/db/migrations): in sync with its source, every source body byte-identical,
// names in the platform's <digits>_<slug>.sql order, the generator refuses to change or drop an applied file; on the throwaway
// cluster a NON-superuser owner login (as the platform hands out) gets from the folder alone — applied by a runner that opens
// no transaction and by one that wraps each file in its own — the same schema as db/migrate.js, the same migration record,
// the role grants, and the CLI then refuses a direct run; a login without BYPASSRLS fails on the first file with a clear
// message and nothing is applied.

const test = require('node:test');
const assert = require('node:assert');
const fs = require('fs');
const os = require('os');
const path = require('path');
const cp = require('child_process');
const D = require('./_db');
const { createDb } = require('../core/db');
const PM = require('../db/platform-migrations');
const { listMigrations } = require('../db/migrate');

test.describe('platform migrations folder (no database)', () => {
  test('the folder equals the generator output (node server/db/platform-migrations.js --check)', () => {
    assert.deepStrictEqual(PM.check(), []);
    const r = cp.spawnSync(process.execPath, [path.join(__dirname, '..', 'db', 'platform-migrations.js'), '--check'], { encoding: 'utf8' });
    assert.strictEqual(r.status, 0, r.stderr);
  });

  test('names: <digits>_<slug>.sql, source order kept, platform steps in their own slots', () => {
    const files = PM.build();
    const names = files.map((f) => f.name);
    assert.deepStrictEqual(names, names.slice().sort(), 'lexicographic = intended order');
    names.forEach((n) => assert.match(n, /^\d+_[a-z0-9_]+\.sql$/));
    assert.strictEqual(names[0], '0000_platform_roles.sql');
    assert.deepStrictEqual(files.filter((f) => f.source).map((f) => f.source), listMigrations().map((m) => m.name), 'every source, same order');
    assert.strictEqual(PM.platformName('001-schema.sql'), '0010_schema.sql');
    assert.strictEqual(PM.platformName('050-code-scope.sql'), '0500_code_scope.sql');
    names.filter((n) => /_platform_/.test(n)).forEach((n) => assert.match(n, PM.PLATFORM_RE));
    files.filter((f) => f.source).forEach((f) => assert.match(f.name, /^\d{3}0_/, 'a source never takes a platform slot'));
  });

  test('every source body is byte-identical inside its explicit transaction, with its record', () => {
    const src = new Map(listMigrations().map((m) => [m.name, m]));
    PM.build().filter((f) => f.source).forEach((f) => {
      const m = src.get(f.source);
      const a = f.text.indexOf('-- ── source body START ──\n') + '-- ── source body START ──\n'.length;
      const b = f.text.indexOf('\n-- ── source body END ──');
      assert.strictEqual(f.text.slice(a, b), m.text.endsWith('\n') ? m.text : m.text + '\n', f.name);
      if (f.source <= '050-code-scope.sql') {
        assert.match(f.text, /^(--[^\n]*\n)+BEGIN;\n/, 'an applied file keeps its own transaction');
        assert.ok(f.text.endsWith('\nCOMMIT;\n'));
      } else {
        // later files run inside the platform runner's transaction: an own COMMIT ended it and failed the deploy
        assert.ok(!/^\s*(BEGIN|COMMIT|ROLLBACK|END)\s*;/im.test(f.text.slice(0, a) + f.text.slice(b)), f.name + ': no transaction control in the wrapper');
        assert.ok(!/^\s*(BEGIN|COMMIT|ROLLBACK)\s*;/im.test(m.text), f.name + ': no transaction control in the source body');
        assert.match(f.text, /^(--[^\n]*\n)+SET search_path = wts, pg_temp;\n/, 'session search_path first');
        assert.ok(f.text.includes('\nRESET search_path;\n'));
      }
      assert.ok(f.text.includes("VALUES ('" + m.name + "', '" + m.sha + "')"), 'records the source name and digest');
    });
    const exp = PM.build().find((f) => f.name === '0501_platform_export_role.sql').text;
    assert.ok(exp.includes(fs.readFileSync(path.join(__dirname, '..', 'ops', 'sql', 'backup-role.sql'), 'utf8')));
  });

  test('--write refuses to change or remove an existing file without --force', () => {
    const dir = fs.mkdtempSync(path.join(os.tmpdir(), 'wts-pm-'));
    try {
      assert.ok(PM.write(dir).length >= 6);
      assert.deepStrictEqual(PM.write(dir), [], 'idempotent');
      fs.appendFileSync(path.join(dir, '0010_schema.sql'), '-- edited\n');
      assert.throws(() => PM.write(dir), /exists with other content/);
      fs.writeFileSync(path.join(dir, '0600_orphan.sql'), 'select 1;\n');
      assert.match(PM.check(dir).join('\n'), /0010_schema\.sql: differs[\s\S]*0600_orphan\.sql: has no source/);
      assert.throws(() => PM.write(dir), /exists with other content|has no source/);
      PM.write(dir, { force: true });
      assert.deepStrictEqual(PM.check(dir), []);
    } finally { fs.rmSync(dir, { recursive: true, force: true }); }
  });
});

const skip = !D.available() && 'no throwaway database (run through server/test/run.js)';
const ROLES = ['wts_owner', 'wts_definer', 'wts_api', 'wts_jobs', 'wts_support', 'wts_backup'];

async function fingerprint(sql) {
  const tables = (await sql`select c.relname, c.relforcerowsecurity, pg_get_userbyid(c.relowner) as o from pg_class c join pg_namespace n on n.oid = c.relnamespace
    where n.nspname = 'wts' and c.relkind = 'r' order by 1`).map((r) => r.relname + ':' + r.relforcerowsecurity + ':' + r.o);
  const fns = (await sql`select p.oid::regprocedure::text as f, pg_get_userbyid(p.proowner) as o, p.prosecdef from pg_proc p join pg_namespace n on n.oid = p.pronamespace
    where n.nspname = 'wts' order by 1`).map((r) => r.f + ':' + r.o + ':' + r.prosecdef);
  const pols = (await sql`select tablename || '.' || policyname as p from pg_policies where schemaname = 'wts' order by 1`).map((r) => r.p);
  const grants = (await sql`select table_name || ':' || grantee || ':' || privilege_type as g from information_schema.role_table_grants
    where table_schema = 'wts' and grantee like 'wts\\_%' and grantee <> 'wts_backup' order by 1`).map((r) => r.g);
  const pub = (await sql`select count(*)::int as n from pg_class c join pg_namespace n on n.oid = c.relnamespace where n.nspname = 'public' and c.relname <> 'wts_schema_migrations'`)[0].n;
  return { tables, fns, pols, grants, pub };
}
const files = () => PM.build();

test.describe('platform migrations on a one-login database', { skip }, () => {
  let H = null;
  const made = [];
  async function platformDb(name, login, attrs) {
    await H.admin.sql.unsafe(`DO $$ BEGIN IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = '${login}') THEN
      CREATE ROLE ${login} LOGIN NOSUPERUSER ${attrs}; END IF; END $$`);
    await H.admin.sql.unsafe('DROP DATABASE IF EXISTS ' + name);
    await H.admin.sql.unsafe('CREATE DATABASE ' + name + ' OWNER ' + login);
    // the wts_* roles are cluster-wide and exist already here; on the platform the login creates them itself and so holds
    // ADMIN OPTION on each (PostgreSQL 16) — the same state
    for (const r of await H.admin.sql`select rolname from pg_roles where rolname = any(${ROLES})`) {
      await H.admin.sql.unsafe('GRANT ' + r.rolname + ' TO ' + login + ' WITH ADMIN TRUE, INHERIT FALSE, SET FALSE');
    }
    const conn = Object.assign({}, H.conn, { user: login, database: name });
    const d = createDb(conn, { max: 1 }); made.push(d);
    return { conn, d, url: 'postgresql://' + login + '@' + conn.host + ':' + conn.port + '/' + name + '?sslmode=disable' };
  }
  test.before(async () => { H = await D.freshDatabase('pm_reference'); });
  test.after(async () => { for (const d of made) { try { await d.close(); } catch (e) { /* closed */ } } if (H) await H.close(); });

  for (const mode of ['no runner transaction', 'runner transaction per file']) {
    test('the folder alone (' + mode + '): same schema as db/migrate.js, record, grants, idempotent platform steps', async () => {
      const p = await platformDb(mode.startsWith('no') ? 'wts_t_pm_plain' : 'wts_t_pm_wrapped', 'wts_pf_login', 'CREATEROLE BYPASSRLS');
      const apply = (text) => (mode.startsWith('no') ? p.d.sql.unsafe(text) : p.d.sql.begin((tx) => tx.unsafe(text)));
      for (const f of files()) await apply(f.text);
      assert.deepStrictEqual(await fingerprint(p.d.sql), await fingerprint(H.admin.sql), 'objects, owners, forced RLS, policies, grants');
      const ro = await p.d.sql`select bool_and(has_table_privilege('wts_backup', c.oid, 'SELECT')) as r, bool_or(has_table_privilege('wts_backup', c.oid, 'INSERT')) as w
        from pg_class c join pg_namespace n on n.oid = c.relnamespace where n.nspname = 'wts' and c.relkind = 'r'`;
      assert.deepStrictEqual([ro[0].r, ro[0].w], [true, false], 'the export role reads every table and writes none');
      const rec = (await p.d.sql`select name, sha256 from public.wts_schema_migrations order by name`).map((r) => r.name + ':' + r.sha256);
      assert.deepStrictEqual(rec, listMigrations().map((m) => m.name + ':' + m.sha), 'the export manifest sees the source history');
      const m = await p.d.sql`select r.rolname, bool_or(a.inherit_option) as i, bool_or(a.set_option) as s from pg_auth_members a join pg_roles r on r.oid = a.roleid
        join pg_roles me on me.oid = a.member where me.rolname = 'wts_pf_login' group by 1 order by 1`;
      assert.deepStrictEqual(m.map((x) => x.rolname + ':' + x.i + ':' + x.s), ['wts_api:false:true', 'wts_backup:false:true', 'wts_definer:true:true',
        'wts_jobs:false:true', 'wts_owner:true:true', 'wts_support:false:true']);
      // the platform steps are idempotent (cluster-wide state may already be there)
      for (const f of files().filter((x) => /_platform_/.test(x.name))) await apply(f.text);
      // the request role works under forced RLS
      const api = createDb(p.conn, { role: 'wts_api', max: 1 }); made.push(api);
      assert.strictEqual((await api.anon((tx) => tx`select current_user as u`))[0].u, 'wts_api');
      assert.strictEqual((await api.asUser('00000000-0000-4000-8000-000000000001', (tx) => tx`select count(*)::int as n from wts.users`))[0].n, 0);
      // the command line refuses a direct run on a platform-managed database
      const r = cp.spawnSync(process.execPath, [path.join(__dirname, '..', 'db', 'migrate.js'), '--platform'],
        { env: Object.assign({}, process.env, { WTS_MIGRATE_DB_URL: p.url }), encoding: 'utf8' });
      assert.strictEqual(r.status, 2, r.stdout + r.stderr);
      assert.match(r.stderr, /migrated by the platform deploy[\s\S]*refused/);
      assert.ok(!(r.stdout + r.stderr).includes('postgresql://'));
    });
  }

  test('a login without BYPASSRLS: the first file fails with a clear message, nothing is applied', async () => {
    const p = await platformDb('wts_t_pm_norls', 'wts_pf_norls', 'CREATEROLE NOBYPASSRLS');
    await assert.rejects(p.d.sql.unsafe(files()[0].text), /cannot create BYPASSRLS roles/);
    await p.d.sql.unsafe('ROLLBACK');                       // what any runner does after an error (the file's own BEGIN is still open)
    const left = await p.d.sql`select to_regnamespace('wts') as s, to_regclass('public.wts_schema_migrations') as t`;
    assert.strictEqual(left[0].s, null); assert.strictEqual(left[0].t, null);
    const m = await p.d.sql`select count(*)::int as n from pg_auth_members a join pg_roles me on me.oid = a.member where me.rolname = 'wts_pf_norls' and a.set_option`;
    assert.strictEqual(m[0].n, 0, 'no grant made');
    // and a later file cannot run on its own either (no role grants): fails, leaves nothing
    await assert.rejects(p.d.sql.unsafe(files()[1].text));
    await p.d.sql.unsafe('ROLLBACK');
    assert.strictEqual((await p.d.sql`select to_regnamespace('wts') as s`)[0].s, null);
  });
});
